/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var dlagtm = require( './../lib/ndarray.js' );


// FIXTURES //

var NO_TRANS_A1_B0_RM = require( './fixtures/notrans_a1_b0_rm.json' );
var NO_TRANS_A1_B0_CM = require( './fixtures/notrans_a1_b0_cm.json' );
var TRANS_A1_B0_RM = require( './fixtures/trans_a1_b0_rm.json' );
var TRANS_A1_B0_CM = require( './fixtures/trans_a1_b0_cm.json' );
var NO_TRANS_AN1_B1_RM = require( './fixtures/notrans_an1_b1_rm.json' );
var NO_TRANS_A1_BN1_RM = require( './fixtures/notrans_a1_bn1_rm.json' );
var N_EQ_1_RM = require( './fixtures/n_eq_1_rm.json' );
var OFFSETS = require( './fixtures/offsets.json' );
var LARGE_STRIDES = require( './fixtures/large_strides.json' );
var TRANSPOSE_OFFSETS = require( './fixtures/trans_offsets.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlagtm, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 22', function test( t ) {
	t.strictEqual( dlagtm.length, 22, 'returns expected value' );
	t.end();
});

tape( 'the function returns B unchanged when N is 0', function test( t ) {
	var expected;
	var out;
	var B;

	B = new Float64Array( [ 1.0, 2.0 ] );
	expected = new Float64Array( [ 1.0, 2.0 ] );

	out = dlagtm( 'no-transpose', 0, 2, 1.0, new Float64Array( [] ), 1, 0, new Float64Array( [] ), 1, 0, new Float64Array( [] ), 1, 0, new Float64Array( [] ), 2, 1, 0, 0.0, B, 2, 1, 0 );
	t.strictEqual( out, B, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

tape( 'the function handles NRHS = 0', function test( t ) {
	var expected;
	var out;
	var B;

	// When NRHS is 0, neither beta scaling nor A*X loops execute (inner loop count is 0):
	B = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	expected = new Float64Array( [ 1.0, 2.0, 3.0 ] );

	out = dlagtm( 'no-transpose', 3, 0, 1.0, new Float64Array( [ 1.0, 1.0 ] ), 1, 0, new Float64Array( [ 2.0, 3.0, 4.0 ] ), 1, 0, new Float64Array( [ 1.0, 1.0 ] ), 1, 0, new Float64Array( [] ), 1, 1, 0, 0.0, B, 1, 1, 0 );
	t.strictEqual( out, B, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

tape( 'the function computes B := alpha * A * X + beta * B (no-transpose, alpha=1, beta=0, row-major)', function test( t ) {
	var expected;
	var data;
	var out;
	var B;

	data = NO_TRANS_A1_B0_RM;

	B = new Float64Array( data.B );
	expected = new Float64Array( data.B_out );

	out = dlagtm( data.trans, data.N, data.NRHS, data.alpha, new Float64Array( data.DL ), data.strideDL, data.offsetDL, new Float64Array( data.D ), data.strideD, data.offsetD, new Float64Array( data.DU ), data.strideDU, data.offsetDU, new Float64Array( data.X ), data.strideX1, data.strideX2, data.offsetX, data.beta, B, data.strideB1, data.strideB2, data.offsetB );
	t.strictEqual( out, B, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

